<?php $title='Laporan';$page='reports';$pdo=Database::connection();$grades=$pdo->query('SELECT u.name student,u.class_name,AVG(s.score) average_score,COUNT(s.id) total FROM submissions s JOIN users u ON u.id=s.student_id WHERE s.score IS NOT NULL GROUP BY u.id ORDER BY u.class_name,average_score DESC')->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Laporan Akademik</h1><p>Rekap nilai siswa berdasarkan tugas yang telah dinilai.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Nama Siswa</th><th>Kelas</th><th>Jumlah Tugas Dinilai</th><th>Rata-rata Nilai</th></tr></thead><tbody><?php foreach($grades as $r): ?><tr><td><?= e($r['student']) ?></td><td><?= e($r['class_name']) ?></td><td><?= e($r['total']) ?></td><td><b><?= number_format((float)$r['average_score'],2) ?></b></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/../_dashboard_end.php'; ?>